const listReviewNotifyRecipients = `-- name: ListReviewNotifyRecipients :many
SELECT DISTINCT m.user_id
FROM organization_members m
JOIN users u ON u.id = m.user_id AND u.deleted_at IS NULL
WHERE m.organization_id = $1
  AND EXISTS (
    SELECT 1 FROM user_roles ur
    JOIN role_permissions rp ON rp.role_id = ur.role_id
    JOIN permissions p ON p.id = rp.permission_id
    WHERE ur.user_id = m.user_id AND p.slug = 'tenant.reviews.read'
  )
ORDER BY m.user_id
`

// Members of the organization whose roles grant tenant.reviews.read.
func (q *Queries) ListReviewNotifyRecipients(ctx context.Context, organizationID int64) ([]int64, error) {
	rows, err := q.db.Query(ctx, listReviewNotifyRecipients, organizationID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []int64{}
	for rows.Next() {
		var user_id int64
		if err := rows.Scan(&user_id); err != nil {
			return nil, err
		}
		items = append(items, user_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listReviewRequests = `-- name: ListReviewRequests :many
SELECT r.id, r.uuid, r.kind, r.status, r.skip_reason, r.error, r.channel, r.locale, r.customer_name,
       r.recipient_phone, r.plate, r.send_at, r.deferred, r.sent_at, r.opened_at, r.answered_at,
       r.expires_at, r.score, r.comment, r.is_high, r.google_redirects, r.follow_up_status,
       r.follow_up_note, r.followed_up_at, r.created_at, r.updated_at,
       j.uuid AS job_uuid,
       c.uuid AS customer_uuid,
       COALESCE(NULLIF(TRIM(u.name || ' ' || u.surname), ''), '')::text AS followed_up_by_name
FROM review_requests r
LEFT JOIN service_jobs j ON j.id = r.job_id AND j.organization_id = r.organization_id
LEFT JOIN customers c ON c.id = r.customer_id AND c.organization_id = r.organization_id
LEFT JOIN users u ON u.id = r.followed_up_by
WHERE r.organization_id = $1
  AND ($2::text IS NULL OR r.status = $2
       OR ($2::text = 'scheduled' AND r.status = 'sending'))
  AND ($3::text IS NULL OR r.follow_up_status = $3)
  AND ($4::text IS NULL
       OR ($4::text = 'high' AND r.is_high IS TRUE)
       OR ($4::text = 'low' AND r.is_high IS FALSE))
  AND ($5::smallint IS NULL OR r.score = $5)
  AND ($6::text IS NULL OR r.channel = $6)
  AND ($7::bigint IS NULL OR r.customer_id = $7)
  AND ($8::timestamptz IS NULL OR r.created_at >= $8)
  AND ($9::boolean OR r.kind = 'job')
  AND (
    $10::text IS NULL
    OR r.customer_name ILIKE '%' || $10 || '%'
    OR r.recipient_phone ILIKE '%' || $10 || '%'
    OR r.plate ILIKE '%' || $10 || '%'
    OR r.comment ILIKE '%' || $10 || '%'
  )
ORDER BY
    CASE WHEN $11::text = 'created_at' THEN r.created_at END ASC,
    CASE WHEN $11::text = 'score' THEN r.score END ASC NULLS LAST,
    CASE WHEN $11::text = '-score' THEN r.score END DESC NULLS LAST,
    CASE WHEN $11::text = 'answered_at' THEN r.answered_at END ASC NULLS LAST,
    CASE WHEN $11::text = '-answered_at' THEN r.answered_at END DESC NULLS LAST,
    r.created_at DESC, r.id DESC
LIMIT $13 OFFSET $12
`

